// =====================================================================
// [SCADA-CFG] CONFIGURACIÓN CENTRAL — EDITAR AQUÍ TODOS LOS PARÁMETROS
// Línea de embotellado · 7 estaciones · solo PLC real (sin simulación)
// Contexto en MEMORIA: el histórico de largo plazo vive en Azure vía Ignition.
// =====================================================================
const cfg = {
    // Estaciones en orden físico de la línea. key = prefijo de sus tags HMI_<key>_Estado
    stations: [
        { key: 'LLEN',    name: 'Llenadora' },
        { key: 'TAP',     name: 'Tapadora' },
        { key: 'INS_NIV', name: 'Inspección Nivel/Tapa' },
        { key: 'ETICOD',  name: 'Etiquetado/Codificado' },
        { key: 'INS_FIN', name: 'Inspección Final' },
        { key: 'EMP',     name: 'Empaque' },
        { key: 'PAL',     name: 'Paletizado' }
    ],
    // Tiempo de ciclo ideal por estación (s/botella) — el máximo define el Rendimiento
    cycleSec: [2.0, 1.5, 1.0, 2.5, 1.0, 3.0, 4.0],
    targetPerHour: 400,             // objetivo de producción (botellas buenas/hora)
    pollSec: 0.5,                   // DEBE coincidir con cycletime (ms/1000) del endpoint Jeison
    sampleSec: 15,                  // periodo de muestreo de las gráficas de tendencia
    // Códigos de estado de estación (DINT) según el PLC:
    stateCodes: { 0: 'DESHABILITADA', 10: 'LISTA', 20: 'EN OPERACIÓN', 30: 'CICLO COMPLETADO', 90: 'FALLA' },
    // ------------- [SCADA-TAGS] NOMBRES DE TAGS DEL PLC (EtherNet/IP) -------------
    tags: {
        cmdStart: 'HMI_CMD_Start',
        cmdStop:  'HMI_CMD_Stop',
        cmdReset: 'HMI_CMD_Reset',           // limpia alarmas (panel local + pulso al PLC)
        lineRunning: 'HMI_Linea_Running',    // HMI_Linea_Detenida omitido: complemento exacto
        lineFault:   'HMI_Linea_Fault',      // ESTADO de línea (pinta el mímico), no alarma
        lineSetup:   'HMI_Linea_EnSetup',
        stationState: k => 'HMI_' + k + '_Estado',
        counters: {
            good:        'HMI_PROD_BotellasBuenas',
            rejNivel:    'HMI_PROD_RechazoNivelTapa',
            rejEtiqueta: 'HMI_PROD_RechazoEtiquetaCodigo',
            rejTotal:    'HMI_PROD_TotalRechazos',
            packs:       'HMI_PROD_PacksFormados',
            pallets:     'HMI_PROD_PalletsCompletos'
        },
        // Alarmas = espejo directo de tags BOOL del PLC (sin umbrales locales).
        // INS_NIV no tiene tag de falla: intencional, esa estación no alarma.
        alarms: [
            { tag: 'ALM_General_FallaLinea', code: 'GEN',    text: 'Falla general de línea' },
            { tag: 'ALM_LLEN_Falla',         code: 'LLEN',   text: 'Falla de llenadora' },
            { tag: 'ALM_TAP_Falla',          code: 'TAP',    text: 'Falla de tapadora' },
            { tag: 'ALM_ETICOD_Falla',       code: 'ETICOD', text: 'Falla de etiquetado/codificado' },
            { tag: 'ALM_INS_FIN_Falla',      code: 'INSFIN', text: 'Falla de inspección final' },
            { tag: 'ALM_EMP_Falla',          code: 'EMP',    text: 'Falla de empaque' },
            { tag: 'ALM_PAL_Falla',          code: 'PAL',    text: 'Falla de robot/paletizado' }
        ]
    }
};
global.set('scada_cfg', cfg);

// Estado inicial (solo si no existe: sobrevive re-deploys, NO reinicios de Node-RED)
if (!global.get('scada_plant')) {
    global.set('scada_plant', {
        line: { running: false, fault: false, setup: false },
        stations: cfg.stations.map(s => ({ key: s.key, name: s.name, code: 0 })),
        counters: { good: 0, rejNivel: 0, rejEtiqueta: 0, rejTotal: 0, packs: 0, pallets: 0 },
        // Disponibilidad = (op + setup) / total  — acordado con el usuario
        time: { total: 0, op: 0, setup: 0 }
    });
}
if (!global.get('scada_alarms')) global.set('scada_alarms', []);

node.status({ fill: 'green', shape: 'dot', text: 'Config cargada · 7 estaciones · PLC' });
return { topic: 'config', payload: 'config_ok' };

// [SCADA-CMD] Comandos de la UI: start / stop / reset de alarmas.
// Salida 1: eco (debug). Salida 2: escritura al PLC.
const p = global.get('scada_plant');
switch (msg.topic) {
    case 'cmd/start':
    case 'cmd/stop':
        break;                               // el estado real lo confirma el PLC vía lectura
    case 'cmd/reset':
        global.set('scada_alarms', []);      // limpia el panel local; el PLC recibe el pulso
        break;
    default: return null;
}
node.status({ fill: 'blue', shape: 'dot', text: msg.topic });
return [msg, msg];

// [SCADA-PLC-READ] Tags EtherNet/IP -> objeto 'plant' + acumulación de tiempos.
// Se ejecuta a cada ciclo de polling del endpoint (pollSec). Payload esperado
// en modo "all": objeto plano { nombreTag: valor }. Verificar con el debug.
const cfg = global.get('scada_cfg');
const p   = global.get('scada_plant');
if (!cfg || !p) return null;
const t = msg.payload;
if (typeof t !== 'object' || t === null) return null;

// --- Estado de línea ---
p.line.running = !!t[cfg.tags.lineRunning];
p.line.fault   = !!t[cfg.tags.lineFault];
p.line.setup   = !!t[cfg.tags.lineSetup];

// --- Estado por estación (DINT: 0/10/20/30/90) ---
p.stations.forEach(st => {
    const v = t[cfg.tags.stationState(st.key)];
    if (v !== undefined) st.code = v;
});

// --- Contadores de producción (los lleva el PLC; aquí solo se reflejan) ---
for (const [k, tag] of Object.entries(cfg.tags.counters)) {
    if (t[tag] !== undefined) p.counters[k] = t[tag];
}

// --- Bits de alarma crudos (los consume [SCADA-ALM]) ---
p.almBits = {};
cfg.tags.alarms.forEach(a => { p.almBits[a.code] = !!t[a.tag]; });

// --- Tiempos para Disponibilidad: A = (op + setup) / total ---
// 'total' corre siempre que el PLC responde (planta encendida).
p.time.total += cfg.pollSec;
if (p.line.running) p.time.op    += cfg.pollSec;
if (p.line.setup)   p.time.setup += cfg.pollSec;

global.set('scada_plant', p);
node.status({ fill: p.line.fault ? 'red' : (p.line.running ? 'green' : 'grey'),
              shape: 'dot',
              text: (p.line.fault ? 'FALLA' : (p.line.setup ? 'SETUP' : (p.line.running ? 'RUN' : 'STOP')))
                    + ' · ' + p.counters.good + ' bot.' });
return { topic: 'plant', payload: p };

// [SCADA-PLC-WRITE] Traduce comandos de la UI a escrituras de tags del PLC.
const cfg = global.get('scada_cfg');
if (!cfg) return null;
const map = {
    'cmd/start': cfg.tags.cmdStart,
    'cmd/stop':  cfg.tags.cmdStop,
    'cmd/reset': cfg.tags.cmdReset
};
const tag = map[msg.topic];
if (!tag) return null;
// El PLC debe auto-resetear estos BOOL tras consumirlos (pulso).
return { payload: true, variable: tag };

// [SCADA-KPI] Disponibilidad y Rendimiento (OEE total y Calidad eliminados por diseño).
// Disponibilidad = (t_operación + t_setup) / t_total_encendida   (definición acordada)
// Rendimiento    = ciclo_ideal_cuello_botella × botellas_procesadas / t_operación
const cfg = global.get('scada_cfg');
if (!cfg || msg.topic !== 'plant') return null;
const p = msg.payload;
const T = p.time;
const A = T.total > 0 ? (T.op + T.setup) / T.total : 0;
const procesadas = p.counters.good + p.counters.rejTotal;
const ideal = Math.max(...cfg.cycleSec);
const P = T.op > 0 ? Math.min((ideal * procesadas) / T.op, 1) : 0;
const kpi = { A, P };
global.set('scada_kpi', kpi);
node.status({ fill: 'green', shape: 'ring',
              text: 'A ' + (A * 100).toFixed(1) + '% · P ' + (P * 100).toFixed(1) + '%' });
return { topic: 'kpi', payload: kpi };

// [SCADA-ALM] Espejo de las alarmas del PLC (sin umbrales locales).
// Mantiene timestamp de primera activación para el panel.
const cfg = global.get('scada_cfg');
if (!cfg || msg.topic !== 'plant') return null;
const bits = msg.payload.almBits || {};
let alarms = global.get('scada_alarms') || [];
const now = Date.now();

cfg.tags.alarms.forEach(def => {
    const active = !!bits[def.code];
    let a = alarms.find(x => x.code === def.code);
    if (active && !a)      alarms.push({ code: def.code, text: def.text, ts: now, active: true });
    else if (active && a)  a.active = true;
    else if (!active && a) a.active = false;
});
alarms = alarms.filter(a => a.active || (now - a.ts) < 3600000);  // inactivas visibles 1 h en contexto
global.set('scada_alarms', alarms);

const act = alarms.filter(a => a.active);
node.status(act.length ? { fill: 'red', shape: 'dot', text: act.length + ' alarma(s)' }
                       : { fill: 'green', shape: 'dot', text: 'Sin alarmas' });
return { topic: 'alarms', payload: act };

// [SCADA-UI] Contadores -> textos de la ventana General (8 salidas).
if (msg.topic !== 'plant') return null;
const cfg = global.get('scada_cfg');
const p = msg.payload, c = p.counters;
const expected = Math.floor(cfg.targetPerHour * (p.time.op / 3600));
let estado = 'DETENIDA';
if (p.line.fault) estado = '⚠ FALLA';
else if (p.line.setup) estado = 'EN SETUP';
else if (p.line.running) estado = 'EN MARCHA';
return [
    { payload: c.good },
    { payload: c.rejNivel },
    { payload: c.rejEtiqueta },
    { payload: c.rejTotal },
    { payload: c.packs },
    { payload: c.pallets },
    { payload: c.good + ' / ' + expected + ' bot.' },
    { payload: estado }
];

// [SCADA-UI] KPI -> 2 gauges (Disponibilidad, Rendimiento).
if (msg.topic !== 'kpi') return null;
const k = msg.payload;
const pct = v => Math.round(v * 1000) / 10;
return [{ payload: pct(k.A) }, { payload: pct(k.P) }];

// [SCADA-MIMIC] Estado de planta / alarmas -> comandos set_style / update_text del ui_svg.
// Colores por código DINT de estación: 0 gris, 10 azul, 20 verde, 30 cian, 90 rojo.
const BODY = { 0: '#616161', 10: '#1e88e5', 20: '#43a047', 30: '#26c6da', 90: '#e53935' };
const LAMP = { 0: '#9e9e9e', 10: '#64b5f6', 20: '#76ff03', 30: '#80deea', 90: '#ff1744' };

if (msg.topic === 'plant') {
    const cfg = global.get('scada_cfg');
    const p = msg.payload;
    const cmds = [];
    p.stations.forEach((st, i) => {
        const n = i + 1;
        cmds.push({ command: 'set_style', selector: '#Station' + n + '_1',    attributeName: 'fill', attributeValue: BODY[st.code] || '#616161' });
        cmds.push({ command: 'set_style', selector: '#Station' + n + '_lamp', attributeName: 'fill', attributeValue: LAMP[st.code] || '#9e9e9e' });
        cmds.push({ command: 'update_text', selector: '#st' + n + '_value',
                    textContent: (cfg.stateCodes[st.code] || ('COD ' + st.code)) });
    });
    cmds.push({ command: 'update_text', selector: '#output_value',  textContent: String(p.counters.good) });
    cmds.push({ command: 'update_text', selector: '#packs_value',   textContent: String(p.counters.packs) });
    cmds.push({ command: 'update_text', selector: '#pallets_value', textContent: String(p.counters.pallets) });
    cmds.push({ command: 'update_text', selector: '#rej_value',     textContent: String(p.counters.rejTotal) });
    cmds.push({ command: 'set_style', selector: '#belt_arrows', attributeName: 'opacity', attributeValue: p.line.running ? '1' : '0.15' });
    let txt = 'LÍNEA DETENIDA', col = '#757575';
    if (p.line.fault)       { txt = '⚠ FALLA DE LÍNEA'; col = '#b71c1c'; }
    else if (p.line.setup)  { txt = 'LÍNEA EN SETUP';   col = '#f9a825'; }
    else if (p.line.running){ txt = 'LÍNEA EN MARCHA';  col = '#2e7d32'; }
    cmds.push({ command: 'update_text', selector: '#line_state_value', textContent: txt });
    cmds.push({ command: 'set_style', selector: '#line_state_box', attributeName: 'fill', attributeValue: col });
    return { payload: cmds };
}

if (msg.topic === 'alarms') {
    const act = msg.payload || [];
    const txt = act.length ? ('\u26A0 ' + act[0].text + (act.length > 1 ? '  (+' + (act.length - 1) + ' más)' : '')) : '';
    return { payload: [
        { command: 'set_style', selector: '#alarm_banner', attributeName: 'display', attributeValue: act.length ? 'inline' : 'none' },
        { command: 'set_style', selector: '#alarm_text',   attributeName: 'display', attributeValue: act.length ? 'inline' : 'none' },
        { command: 'update_text', selector: '#alarm_text', textContent: txt }
    ] };
}
return null;

// [SCADA-HIST] Muestreo para tendencias locales (solo memoria del chart; el
// histórico de largo plazo se envía a Azure vía Ignition, fuera de este flujo).
const p = global.get('scada_plant');
if (!p) return null;
const c = p.counters;
const tot = c.good + c.rejTotal;
const defPct = tot > 0 ? 100 * c.rejTotal / tot : 0;
return [
    { topic: 'Producción',  payload: c.good },
    { topic: 'Defectos %',  payload: +defPct.toFixed(1) }
];
